/* Typed SDK8/9 buffer construction/storage andbound draw acceptance. */
typedef struct TCContext{TCDevice*d;HMODULE module;UINT mode;BOOL core;}TCContext;
static HRESULT bc_vb(TCContext*,UINT,DWORD,DWORD,UINT,TCVB**);
static HRESULT bc_ib(TCContext*,UINT,DWORD,UINT,UINT,TCIB**);
static HRESULT bc_stream(TCContext*,TCVB*);
static HRESULT bc_indices(TCContext*,TCIB*);
static void bc_bind_queries(TCContext*,TCVB*,TCIB*);
static HRESULT bc_indexed(TCContext*);
static HRESULT tc_fvf(TCDevice*);
static void tc_read(TCContext*);
static HRESULT tc_reset(TCContext*);
static void tc_check(BOOL ok,const char*s){if(!ok){tc_report(s);ExitProcess(1);}}
static void tc_expect(HRESULT hr,const char*s){tc_check(SUCCEEDED(hr),s);}
typedef struct{float x,y,z,w;DWORD color;}BVertex;
static void bc_vertices(void*data,DWORD color){const float xy[4][2]={{-.5f,-.5f},{7.5f,-.5f},{-.5f,7.5f},{7.5f,7.5f}};BVertex*v=data;for(UINT n=0;n<4;n++)v[n]=(BVertex){xy[n][0],xy[n][1],.5f,1,color};}
static void bc_capture(TCContext*c,UINT step,BOOL indexed){tc_expect(TC_CLEAR(c->d,0,NULL,1,0xff010203,1,0),"FAIL buffers clear");tc_expect(TC_BEGIN(c->d),"FAIL buffers scene");tc_expect(indexed?bc_indexed(c):TC_DRAW(c->d,D3DPT_TRIANGLESTRIP,0,2),"FAIL bound buffer draw");tc_expect(TC_END(c->d),"FAIL buffers end scene");tc_read(c);char line[160];wsprintfA(line,"BUFCORE FRAME index=%u mode=%u step=%u indexed=%u readback=1",tc_frame_index++,c->mode,step,indexed);tc_report(line);}
static void tc_cases(TCContext*c){
 tc_expect(TC_RS(c->d,D3DRS_ZENABLE,FALSE),"FAIL buffers Z");tc_expect(TC_RS(c->d,D3DRS_LIGHTING,FALSE),"FAIL buffers lighting");tc_expect(TC_RS(c->d,D3DRS_CULLMODE,D3DCULL_NONE),"FAIL buffers cull");tc_expect(tc_fvf(c->d),"FAIL buffers FVF");tc_expect(TC_TSS(c->d,0,D3DTSS_COLOROP,D3DTOP_SELECTARG2),"FAIL buffers op");tc_expect(TC_TSS(c->d,0,D3DTSS_COLORARG2,D3DTA_DIFFUSE),"FAIL buffers argument");tc_expect(TC_TSS(c->d,0,D3DTSS_ALPHAOP,D3DTOP_SELECTARG2),"FAIL buffers alpha");tc_expect(TC_TSS(c->d,0,D3DTSS_ALPHAARG2,D3DTA_DIFFUSE),"FAIL buffers alpha argument");
 for(UINT n=0;n<3;n++){TCVB*out=(void*)99;tc_check(bc_vb(c,n==0?0:80,512,(D3DFVF_XYZRHW|D3DFVF_DIFFUSE),n==1?4:0,n==2?NULL:&out)==D3DERR_INVALIDCALL&&(n==2?out==(void*)99:out==NULL),"FAIL VB invalid/output");}
 for(UINT n=0;n<6;n++){TCIB*out=(void*)99;UINT len=n==0?0:n==3?3:n==4?6:12,format=n==2?0:n==4?102:101;tc_check(bc_ib(c,len,512,format,n==1?4:0,n==5?NULL:&out)==D3DERR_INVALIDCALL&&(n==5?out==(void*)99:out==NULL),"FAIL IB invalid/output");}
 TCVB*vb=NULL;TCIB*ib16=NULL,*ib32=NULL;tc_expect(bc_vb(c,80,512,(D3DFVF_XYZRHW|D3DFVF_DIFFUSE),0,&vb),"FAIL vertex buffer create");tc_expect(bc_ib(c,12,512,101,0,&ib16),"FAIL index16 create");tc_expect(bc_ib(c,24,512,102,0,&ib32),"FAIL index32 create");TCVBDesc vd;TCIBDesc id;tc_expect(BC_VDESC(vb,&vd),"FAIL VB descriptor");tc_check(vd.Format==100&&vd.Type==6&&vd.Usage==512&&vd.Pool==0&&vd.Size==80&&vd.FVF==(D3DFVF_XYZRHW|D3DFVF_DIFFUSE),"FAIL VB metadata");tc_expect(BC_IDESC(ib16,&id),"FAIL IB16 descriptor");tc_check(id.Format==101&&id.Type==7&&id.Usage==512&&id.Pool==0&&id.Size==12,"FAIL IB16 metadata");tc_expect(BC_IDESC(ib32,&id),"FAIL IB32 descriptor");tc_check(id.Format==102&&id.Size==24,"FAIL IB32 metadata");TCDevice*parent=NULL;tc_expect(BC_VPARENT(vb,&parent),"FAIL VB parent");tc_check(parent==c->d,"FAIL VB parent identity");TC_DREL(parent);tc_expect(BC_IPARENT(ib16,&parent),"FAIL IB parent");tc_check(parent==c->d,"FAIL IB parent identity");TC_DREL(parent);
 BLockPointer data=NULL;tc_expect(BC_VLOCK(vb,0,0,&data,16),"FAIL VB readonly zero lock");for(UINT n=0;n<80;n++)tc_check(!((BYTE*)data)[n],"FAIL VB zero storage");tc_expect(BC_VUNLOCK(vb),"FAIL VB readonly unlock");tc_expect(BC_VLOCK(vb,0,0,&data,8192),"FAIL VB DISCARD lock");bc_vertices(data,0xffff0000);BLockPointer again=(void*)99;tc_check(BC_VLOCK(vb,0,1,&again,0)==D3DERR_INVALIDCALL&&again==(void*)99,"FAIL duplicate VB lock output");tc_expect(BC_VUNLOCK(vb),"FAIL VB initial upload");tc_check(BC_VUNLOCK(vb)==D3DERR_INVALIDCALL,"FAIL unmatched VB unlock");
 const UINT order16[6]={0,1,2,2,1,3},order32[6]={3,1,2,2,1,0};for(UINT kind=0;kind<2;kind++){TCIB*b=kind?ib32:ib16;tc_expect(BC_ILOCK(b,0,0,&data,8192),"FAIL IB DISCARD lock");for(UINT n=0;n<(kind?24u:12u);n++)tc_check(!((BYTE*)data)[n],"FAIL IB zero storage");for(UINT n=0;n<6;n++){if(kind)((DWORD*)data)[n]=order32[n];else((WORD*)data)[n]=(WORD)order16[n];}tc_expect(BC_IUNLOCK(b),"FAIL index upload");tc_check(BC_IUNLOCK(b)==D3DERR_INVALIDCALL,"FAIL unmatched IB unlock");}
 tc_expect(bc_stream(c,vb),"FAIL buffer stream bind");tc_expect(bc_indices(c,ib16),"FAIL index16 bind");bc_bind_queries(c,vb,ib16);bc_capture(c,0,TRUE);
 tc_expect(BC_VLOCK(vb,16,64,&data,4096),"FAIL VB NOOVERWRITE partial lock");for(UINT n=0;n<4;n++)*(DWORD*)((BYTE*)data+n*20)=0xff0000ff;tc_expect(BC_VUNLOCK(vb),"FAIL VB partial blue upload");tc_expect(BC_VLOCK(vb,16,64,&data,16),"FAIL VB readonly partial");for(UINT n=0;n<4;n++)tc_check(*(DWORD*)((BYTE*)data+n*20)==0xff0000ff,"FAIL VB readonly preserved bits");tc_expect(BC_VUNLOCK(vb),"FAIL VB readonly partial unlock");bc_capture(c,1,TRUE);
 tc_expect(BC_VLOCK(vb,0,0,&data,8192),"FAIL VB DISCARD green lock");bc_vertices(data,0xff00ff00);tc_expect(BC_VUNLOCK(vb),"FAIL VB green upload");tc_expect(bc_indices(c,ib32),"FAIL index32 bind");bc_bind_queries(c,vb,ib32);bc_capture(c,2,TRUE);
 tc_expect(BC_VLOCK(vb,16,64,&data,4096),"FAIL VB NOOVERWRITE purple lock");for(UINT n=0;n<4;n++)*(DWORD*)((BYTE*)data+n*20)=0xff8000ff;tc_expect(BC_VUNLOCK(vb),"FAIL VB purple upload");bc_capture(c,3,FALSE);tc_expect(bc_stream(c,NULL),"FAIL stream unbind");tc_expect(bc_indices(c,NULL),"FAIL indices unbind");tc_check(!BC_VREL(vb)&&!BC_IREL(ib16)&&!BC_IREL(ib32),"FAIL buffer final refs");tc_expect(tc_reset(c),"FAIL buffers Reset");char line[220];wsprintfA(line,"BUFCORE CHECK mode=%u invalidCases=9 VBSize=80 IB16Size=12 IB32Size=24 zeroStorage=1 readonly=1 partialOffset=16 bindIdentity=1 reset=1 finalRefs=0",c->mode);tc_report(line);
}
